import StateMachine from '../../src/vendors/dfa/index.js';
import useData from '../../src/fontkit/opentype/shapers/use.js';
import { unzlibSync } from 'fflate';
import trieArabic from '../../src/fontkit/opentype/shapers/trie.js';
import trieIndic from '../../src/fontkit/opentype/shapers/trieIndic.js';
import trieUse from '../../src/fontkit/opentype/shapers/trieUse.js';
import { decodeBase64 } from '../../src/fontkit/utils.js';
import { UnicodeTrie } from '../../src/vendors/unicode-properties/UnicodeTrie.js';
// Generated by scripts/reencode-shaper-tries.mjs from the source tries
// (Arabic checked against ArabicShaping.txt, USE regenerated from UCD);
// the script itself checks every code point. The trieUse.ts values are
// rewritten by `scripts/gen-use-trie.mjs <ucd> --write`.
import fixture from './shaperTries.fixture.json' with { type: 'json' };

const tries: Record<string, string> = {
  'trie.ts': trieArabic,
  'trieIndic.ts': trieIndic,
  'trieUse.ts': trieUse,
};

const load = (b64: string) => new UnicodeTrie(unzlibSync(decodeBase64(b64)));

describe('fontkit shaper tries', () => {
  it('trie.ts holds Arabic joining classes (value - 1)', () => {
    const trie = load(trieArabic);
    expect(trie.get(0x0627) - 1).toBe(2); // ALEF: Right_Joining
    expect(trie.get(0x0628) - 1).toBe(3); // BEH: Dual_Joining
    expect(trie.get(0x064b)).toBe(0); // FATHATAN: unlisted, Mn fallback
    expect(trie.get(0x0710) - 1).toBe(4); // SYRIAC ALAPH
    expect(trie.get(0x0041)).toBe(0);
  });

  it('trieUse.ts holds USE categories (indices into use.ts categories)', () => {
    const trie = load(trieUse);
    // use.ts categories: 0=O 4=B 7=VMAbv 9=VAbv 10=VPst 11=CMBlw 13=VBlw
    // 14=H 16=CMAbv 18=CS 20=SUB 27=SMAbv
    expect(trie.get(0x0041)).toBe(0); // O
    expect(trie.get(0x1780)).toBe(4); // KHMER KA: B
    expect(trie.get(0x17b6)).toBe(10); // KHMER AA: VPst
    expect(trie.get(0x17d2)).toBe(14); // KHMER COENG: H
    // USE specification overrides (scripts/gen-use-trie.mjs):
    expect(trie.get(0x0f71)).toBe(11); // TIBETAN AA: Nukta, CMBlw
    expect(trie.get(0x0f00)).toBe(4); // TIBETAN OM: Consonant, B
    expect(trie.get(0x0f86)).toBe(7); // TIBETAN LCI RTAGS: Tone_Mark, VMAbv

    for (const cp of [0x0f72, 0x0f7a, 0x0f7b, 0x0f7c, 0x0f7d, 0x0f80]) {
      expect(trie.get(cp)).toBe(13); // I/E/O: VBlw, grammar position
    }

    expect(trie.get(0x0f74)).toBe(9); // U: VAbv, grammar position
    expect(trie.get(0x0f90)).toBe(20); // TIBETAN SUBJOINED KA: SUB
    expect(trie.get(0x1b34)).toBe(16); // BALINESE REREKAN: CMAbv
    expect(trie.get(0x1b6b)).toBe(27); // BALINESE MUSICAL TEGEH: SMAbv
    expect(trie.get(0xa9c0)).toBe(14); // JAVANESE PANGKON: H
    expect(trie.get(0x11003)).toBe(18); // BRAHMI JIHVAMULIYA: CS
  });

  it('still needs the mapped-II / TSA -PHRU compatibility exception', () => {
    const trie = load(trieUse);
    const data = JSON.parse(new TextDecoder().decode(unzlibSync(decodeBase64(useData))));
    const machine = new StateMachine(data);
    expect(Array.from(machine.match([0x0f40, 0x0f73, 0x0f39].map((cp) => trie.get(cp)))))
      .toEqual([[0, 1, ['standard_cluster']], [2, 2, ['broken_cluster']]]);
  });

  it('trieIndic.ts resolves supplementary code points', () => {
    // HEAD misread highStart as 0x1100, so every supplementary code point
    // returned the trie's final value.
    expect(load(trieIndic).get(0x11013)).not.toBe(load(trieIndic).get(0x10ffff));
  });

  for (const [file, b64] of Object.entries(tries)) {
    it(`${file} matches the original unicode-trie lookups`, () => {
      const trie = new UnicodeTrie(unzlibSync(decodeBase64(b64)));
      const expected = (fixture.values as Record<string, number[]>)[file]!;
      expect(expected).toHaveLength(fixture.codePoints.length);
      const actual = fixture.codePoints.map((cp) => trie.get(cp));
      expect(actual).toEqual(expected);
    });
  }
});
